#!/usr/bin/env bash
source /home/ubuntu/capstone/assets/solution-lib.bash
# Собираем backup-набор: XML, inventory volumes, копию data volume, dump и checksums.
D=/home/ubuntu/capstone/15-backup/set; ensure_dir "$D"; for vm in cap-edge cap-app cap-db; do "${VIRSH[@]}" dumpxml "$vm" --config >"$D/$vm.xml"; done; for n in cap-front cap-back; do "${VIRSH[@]}" net-dumpxml "$n" >"$D/$n.xml"; done; "${VIRSH[@]}" pool-dumpxml capstone-pool >"$D/capstone-pool.xml"; "${VIRSH[@]}" vol-list capstone-pool --details >"$D/volumes.txt"; src=$("${VIRSH[@]}" vol-path --pool capstone-pool cap-db-data.qcow2); /usr/bin/sudo -n /usr/bin/cp --sparse=always "$src" "$D/cap-db-data.qcow2"; /usr/bin/curl -fsS http://192.168.151.30:54321/orders >"$D/orders.json"; /usr/bin/printf '{"name":"capstone-backup","critical_volume":"cap-db-data.qcow2","database_dump":"orders.json"}\n' >"$D/manifest.json"; (cd "$D" && /usr/bin/sha256sum cap-edge.xml cap-app.xml cap-db.xml cap-front.xml cap-back.xml capstone-pool.xml volumes.txt cap-db-data.qcow2 orders.json manifest.json >SHA256SUMS); /usr/bin/sudo -n /usr/bin/chown -R ubuntu:ubuntu /home/ubuntu/capstone/15-backup
